def save(path,obj):
    path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(obj,indent=2,ensure_ascii=False)+'\n')
def c(field,op,value=None):
    x={'field':field,'operator':'missing' if op=='not_exists' else op}
    if value is not None:x['value']=value
    return x
def all_(*nodes):return {'all':list(nodes)}
def any_(*nodes):return {'any':list(nodes)}
def between(f,lo,hi):return all_(c(f,'>',lo),c(f,'<=',hi))
ALIASES={'HYPERSENSITIVITY':'EXCLUSION_HYPERSENSITIVITY','ICI_PNEUMONITIS_G2':'PNEUMONITIS_G2','ICI_PNEUMONITIS_G3':'PNEUMONITIS_G3_G4','ICI_COLITIS_G2':'COLITIS_G2_G3','ICI_COLITIS_G4':'COLITIS_G4','ICI_HEPATITIS_WITHHOLD':'HEPATITIS_WITHHOLD','ICI_HEPATITIS_STOP':'HEPATITIS_PERMANENT','ICI_RENAL_G2':'NEPHRITIS_G2','ICI_RENAL_G3':'NEPHRITIS_G3_G4','ICI_INFUSION_G3':'INFUSION_REACTION_G3_G4'}
manifest={'release':'0.84.22','checked':DATE,'clinical_use_authorised':False,'protocols':{}}
for code,version,days,cycles,dose,unit in [('00576','5',14,26,10,'mg/kg'),('00655','3a',28,13,1500,'mg')]:
    original=next((ROOT/'protocols/lung').glob(code+'*.json'));p=json.loads(original.read_text());url=SOURCES[code]['url']
    d=p['input_definitions'];rules=[]
    def field(key,label,type='boolean',**extra):
        item={'label':label,'type':type,'required':False,'input_role':'decision',**extra}
        if type=='boolean':item['demo_value']=False
        d[key]=item
    def number(key,label,unit='',**extra):field(key,label,'number',**{'min':0,'step':.01,'unit':unit,**extra})
    def select(key,label,options,**extra):field(key,label,'select',options=[{'value':v,'label':t} for v,t in options],**extra)
    def grade(key,label):
        select(key,label+' (source CTCAE 4.03; confirm event-specific grade)',[(i,'Absent / grade 0' if i==0 else 'Grade '+str(i)) for i in range(5)],demo_value=0,ctcae_version='4.03',assessment_guidance='Use the appropriate event-specific CTCAE 4.03 term referenced by NCCP Table 1. A generic grade alone does not diagnose immune toxicity; assess alternative causes. Grade 4 is not defined for every skin or endocrine term.')
    def rule(id,cond,action,text,page,section='Table 1',source_url=None):
        if code=='00655':id=ALIASES.get(id,id)
        rules.append({'rule_id':id,'when':cond,'action':{'type':action,'components':['durvalumab'],'recommendation':text,'message':text},'explanation':text,'source':{'document':('EMA Imfinzi SmPC' if source_url else f'NCCP {code} v{version}'),'page':page,'section':section,'url':source_url or url,'checked':DATE}})
    select('ecog','ECOG performance status',[(i,str(i)) for i in range(5)],demo_value=0)
    select('assessment_type','Assessment context',[('baseline','Before first durvalumab'),('on_treatment','On treatment'),('restart','Considering restart after a hold')],demo_value='on_treatment')
    number('age_years','Age','years');number('pd_l1_percent','PD-L1 tumour-cell expression','%',max=100)
    number('concurrent_platinum_cycles','Platinum cycles concurrent with radiotherapy','cycles',step=1)
    number('radiotherapy_total_gy','Definitive radiation total dose','Gy')
    number('days_since_chemoradiotherapy','Interval from completion of CRT to first durvalumab dose','days',step=1)
    number('cycle_number','Planned durvalumab cycle number','cycle',min=1,step=1,demo_value=1)
    number('treatment_elapsed_months','Elapsed durvalumab course before the planned dose','months')
    number('weight_kg','Current body weight','kg',min=.1)
    for key,label in [('stage_iii_unresectable_nsclc','Stage III unresectable NSCLC confirmed'),('crt_concurrent','Platinum chemotherapy and radiation given concurrently'),('disease_progressed_after_crt','Progression during or after definitive concurrent CRT'),('mixed_sclc_nsclc_histology','Mixed small-cell and non-small-cell histology'),('adequate_organ_function','Adequate haematological, hepatic and renal function confirmed'),('active_infection_requiring_therapy','Active clinically significant infection requiring therapy'),('prior_anti_pd1_pdl1','Prior anti-PD-1 or anti-PD-L1 therapy'),('previous_grade3_plus_irae','Previous grade 3 or worse immune event on prior immunotherapy'),('unresolved_prior_irae_over_grade1','Previous immune event remains above grade 1'),('clinically_significant_autoimmune_disease','Clinically significant autoimmune disease'),('inflammatory_bowel_disease_history','History of inflammatory bowel disease'),('primary_immunodeficiency','History of primary immunodeficiency'),('organ_transplant_immunosuppression','Organ transplant requiring therapeutic immunosuppression'),('prior_crt_pneumonitis_any_grade','Any pneumonitis from previous chemoradiation'),('other_systemic_immunosuppressants','Other systemic immunosuppressive medicines'),('new_worsening_respiratory_symptoms','New or worsening cough, breathlessness or chest symptoms'),('hepatitis_alternative_cause_confirmed','Alternative cause confirmed for concurrent transaminase and bilirubin elevation'),('rash_grade_2_over_one_week','Grade 2 immune rash has persisted for more than one week'),('myositis_respiratory_insufficiency','Myositis with signs of respiratory insufficiency'),('transverse_myelitis','Immune-mediated transverse myelitis, any grade'),('immune_diabetes_suspected','Immune-mediated type 1 diabetes suspected/diagnosed'),('diabetic_ketoacidosis','Suspected/confirmed diabetic ketoacidosis or acute metabolic decompensation'),('endocrine_clinically_stable','Endocrinopathy now clinically stable'),('endocrine_controlled_replacement','Severe/recurrent event is an endocrinopathy controlled by replacement hormones'),('recurrent_grade_3_immune_toxicity','Recurrent grade 3 immune-mediated adverse reaction'),('grade4_event_endocrine','Grade 4 immune event is an endocrinopathy'),('nonimmune_grade4_lab_only','Grade 4 nonimmune event consists only of laboratory abnormalities'),('fbc_clinical_concern','Blood-count result raises a clinical concern')]:field(key,label)
    number('systemic_steroids_mg_pred','Systemic steroid dose, excluding inhaled/topical steroids','mg/day prednisone equivalent',demo_value=0)
    number('rash_duration_days','Duration of current grade 2 immune rash','days')
    number('myositis_days_without_grade1_recovery','Days since myositis onset without recovery to grade 1 or less','days')
    number('weeks_since_immune_hold','Weeks since immune-toxicity treatment hold','weeks')
    number('restart_residual_immune_grade','Residual immune-toxicity grade when considering restart','grade',max=4,step=1)
    number('creatinine_baseline_ratio','Creatinine divided by pretreatment baseline','×baseline')
    number('creatinine_uln_ratio','Creatinine divided by local upper normal limit','×ULN')
    # Keep historical field usable without pretending it is an absolute concentration.
    number('creatinine_ratio_baseline_or_uln','Legacy creatinine ratio: enter the higher of baseline and local-ULN ratios','×baseline or ×ULN',demo_value=1,assessment_guidance='A ratio only, not creatinine in µmol/L. Prefer the separate baseline and ULN fields. Confirm the event is immune nephritis and its source grade.')
    for key,label in [('pneumonitis_grade','Immune pneumonitis'),('diarrhoea_colitis_grade','Immune diarrhoea/colitis'),('rash_grade','Immune rash/dermatitis including pemphigoid'),('infusion_reaction_grade','Infusion-related reaction'),('infection_grade','Infection'),('hyperthyroidism_grade','Immune hyperthyroidism/thyroiditis'),('hypothyroidism_grade','Immune hypothyroidism'),('adrenal_hypophysitis_grade','Immune adrenal insufficiency/hypophysitis/hypopituitarism'),('type1_diabetes_grade','Immune type 1 diabetes'),('myocarditis_grade','Immune myocarditis'),('myositis_grade','Immune myositis/polymyositis'),('myasthenia_grade','Immune myasthenia gravis'),('meningitis_grade','Immune meningitis'),('encephalitis_grade','Immune encephalitis'),('guillain_barre_grade','Immune Guillain-Barré syndrome'),('other_immune_toxicity_grade','Other immune adverse event'),('other_nonimmune_toxicity_grade','Nonimmune adverse event')]:grade(key,label)
    select('endocrine_status','Endocrine clinical context',[('none','No endocrine clinical concern'),('symptomatic_hypothyroidism','Symptomatic hypothyroidism'),('symptomatic_hyperthyroidism_or_thyroiditis','Symptomatic hyperthyroidism/thyroiditis'),('symptomatic_adrenal_insufficiency_or_hypophysitis','Symptomatic adrenal insufficiency/hypophysitis'),('controlled_on_replacement','Endocrinopathy controlled with replacement hormones')],demo_value='none')
    select('renal_impairment_severity','Baseline renal impairment severity',[(x,x.title()) for x in ['none','mild','moderate','severe']])
    select('hepatic_impairment_severity','Baseline hepatic impairment severity',[(x,x.title()) for x in ['none','mild','moderate','severe']])
    # Existing generic neurological input lacks the identity needed to distinguish meningitis.
    if 'serious_neurological_irae_grade' in d:grade('serious_neurological_irae_grade','Legacy unspecified serious immune neurological event')
    for key in ['hypersensitivity','pregnancy','breastfeeding']:
        d[key]['required']=False
    rule('ECOG_OUTSIDE_USUAL_RANGE',c('ecog','>',1),'consultant_review','ECOG above 1 is outside NCCP eligibility (0 or 1); consultant review is required.',1,'Eligibility')
    rule('AGE_ELIGIBILITY',c('age_years','<',18),'consultant_review','These NCCP regimens cover adults aged at least 18; paediatric use is outside this protocol.',1,'Eligibility')
    rule('PDL1_ELIGIBILITY',c('pd_l1_percent','<',1),'consultant_review','PD-L1 below 1% is outside the current NCCP indication. PACIFIC overall-population evidence does not override this criterion.',1,'Indication')
    for key,id,msg in [('stage_iii_unresectable_nsclc','STAGE_SETTING','The NCCP setting is locally advanced unresectable stage III NSCLC; confirm the correct regimen.'),('crt_concurrent','CONCURRENT_CRT_REQUIRED','Sequential CRT is excluded by these NCCP regimens; confirm concurrent definitive platinum CRT.'),('adequate_organ_function','ORGAN_FUNCTION_REVIEW','Adequate organ function is an eligibility condition; assess abnormalities without importing cytotoxic count cut-offs.')]:rule(id,c(key,'==',False),'consultant_review',msg,1,'Eligibility')
    rule('PLATINUM_CYCLES',c('concurrent_platinum_cycles','<',2),'consultant_review','NCCP requires at least two platinum chemotherapy cycles concurrent with radiation.',1,'Eligibility')
    rule('RT_DOSE',c('radiotherapy_total_gy','<',60),'consultant_review','NCCP specifies at least 60 Gy definitive radiation. Review the actual CRT course.',1,'Eligibility')
    rule('CRT_START_WINDOW',c('days_since_chemoradiotherapy','>',42),'consultant_review','Cycle 1 should commence within 42 days of completing CRT; later initiation needs consultant review, not automatic calendar clearance.',1,'Treatment')
    rule('COURSE_CYCLE_LIMIT',c('cycle_number','>',cycles),'consultant_review',f'The source maximum is 12 months ({cycles} cycles); do not automatically extend or compensate for missed doses.',1,'Treatment')
    rule('COURSE_MONTH_LIMIT',c('treatment_elapsed_months','>=',12),'consultant_review','The source course is capped at 12 months. Review completion before any further planned dose.',1,'Treatment')
    if code=='00655':rule('LOW_BODY_WEIGHT_SCHEDULE',c('weight_kg','<=',30),'withhold','Do not administer the fixed 1500 mg dose at body weight ≤30 kg. NCCP requires a separately prescribed weight-based schedule: 10 mg/kg every 2 weeks or 20 mg/kg every 4 weeks until weight is >30 kg. Confirm the interval; no automatic switch or calculated prescription is supplied.',1,'Treatment footnote')
    rule('HYPERSENSITIVITY',c('hypersensitivity','==',True),'contraindicated','History of hypersensitivity to durvalumab or excipients is an exclusion.',2,'Exclusions')
    for key,id,msg in [('disease_progressed_after_crt','DISEASE_PROGRESSION_AFTER_CRT','Progression during or after definitive concurrent CRT is outside this consolidation regimen.'),('mixed_sclc_nsclc_histology','MIXED_HISTOLOGY','Mixed small-cell/non-small-cell histology is excluded by this protocol.'),('previous_grade3_plus_irae','PRIOR_SEVERE_IRAE','Previous grade ≥3 immune toxicity on prior immunotherapy is a source exclusion.'),('unresolved_prior_irae_over_grade1','UNRESOLVED_PRIOR_IRAE','A previous immune adverse event unresolved above grade 1 is a source exclusion.')]:rule(id,c(key,'==',True),'contraindicated',msg,2,'Exclusions')
    rule('ACTIVE_INFECTION_REQUIRING_THERAPY',c('active_infection_requiring_therapy','==',True),'withhold','Active clinically significant infection requiring therapy is a source exclusion; treat and review suitability before durvalumab.',2,'Exclusions')
    rule('BASELINE_IMMUNOSUPPRESSION',all_(c('assessment_type','==','baseline'),any_(c('systemic_steroids_mg_pred','>',10),c('other_systemic_immunosuppressants','==',True))),'withhold','Systemic immunosuppressive corticosteroids >10 mg prednisolone/day equivalent (excluding inhaled/topical) or other immunosuppressants are a baseline exclusion. Review indication and alternatives; do not abruptly stop prescribed steroids.',2,'Exclusions')
    rule('PRIOR_PD1_PDL1_REVIEW',c('prior_anti_pd1_pdl1','==',True),'consultant_review','NCCP directs prior anti-PD-1/PD-L1 use to its separate prior-therapy guidance. Verify current access/clinical policy; this is not an invented blanket contraindication.',2,'Exclusions / prior-therapy cross-reference')
    for key in ['clinically_significant_autoimmune_disease','inflammatory_bowel_disease_history','primary_immunodeficiency','organ_transplant_immunosuppression','prior_crt_pneumonitis_any_grade']:
        rule('CAUTION_'+key.upper(),c(key,'==',True),'consultant_review','NCCP identifies this history as a caution requiring consultant assessment. Any prior CRT pneumonitis needs careful review of radiation, immune and infective causes.',2,'Cautions')
    rule('PREGNANCY_REVIEW',c('pregnancy','==',True),'consultant_review','EMA: durvalumab may cause fetal harm and is not recommended in pregnancy; urgent specialist benefit–risk discussion is required. Effective contraception is advised during treatment and for at least 3 months after.', '14–15','4.6',EMA)
    rule('BREASTFEEDING_REVIEW',c('breastfeeding','==',True),'consultant_review','EMA requires an individual decision whether to discontinue breastfeeding or discontinue/abstain from durvalumab, considering benefits for child and mother; no fabricated fixed breastfeeding washout is supplied.',15,'4.6',EMA)
    rule('RESPIRATORY_SYMPTOMS_REVIEW',c('new_worsening_respiratory_symptoms','==',True),'consultant_review','Promptly assess new/worsening respiratory symptoms before a decision about the next dose. Immune pneumonitis, radiation pneumonitis, infection and progression can resemble each other; obtain appropriate imaging and clinical assessment rather than assuming the cause. This symptom-review trigger is not an assigned pneumonitis grade or an additional NCCP dose-hold threshold.',7,'Pneumonitis precautions')
    for f,g,id,action,text,page in [('pneumonitis_grade',2,'ICI_PNEUMONITIS_G2','withhold','Grade 2 immune pneumonitis: withhold and initiate source-directed immune-toxicity management.',3),('pneumonitis_grade',[3,4],'ICI_PNEUMONITIS_G3','permanently_discontinue','Grade 3–4 immune pneumonitis: permanently discontinue durvalumab.',3),('diarrhoea_colitis_grade',[2,3],'ICI_COLITIS_G2','withhold','Grade 2–3 immune diarrhoea/colitis: withhold durvalumab and assess/treat.',4),('diarrhoea_colitis_grade',4,'ICI_COLITIS_G4','permanently_discontinue','Grade 4 immune diarrhoea/colitis: permanently discontinue.',4)]:rule(id,c(f,'in' if isinstance(g,list) else '==',g),action,text,page)
    rule('ICI_HEPATITIS_WITHHOLD',between('alt_ast_uln_multiple',3,10),'withhold','AST/ALT >3 to ≤10×ULN: withhold for immune-hepatitis assessment. The current NCCP merged table cell includes >5 to ≤10; this is not the permanent-stop threshold. Concurrent bilirubin can change the action.',3)
    rule('ICI_HEPATITIS_STOP',c('alt_ast_uln_multiple','>',10),'permanently_discontinue','AST/ALT >10×ULN: permanently discontinue under the immune-hepatitis table.',3)
    rule('ICI_BILI_WITHHOLD',between('bilirubin_uln_multiple',1.5,3),'withhold','Bilirubin >1.5 to ≤3×ULN: withhold for immune-hepatitis assessment; assess concurrent AST/ALT.',3)
    rule('ICI_BILI_STOP',c('bilirubin_uln_multiple','>',3),'permanently_discontinue','Bilirubin >3×ULN: permanently discontinue under the immune-hepatitis table.',3)
    combo=all_(c('alt_ast_uln_multiple','>',3),c('bilirubin_uln_multiple','>',2))
    rule('HEPATITIS_COMBINED_STOP',all_(combo,c('hepatitis_alternative_cause_confirmed','==',False)),'permanently_discontinue','Concurrent AST/ALT >3×ULN and bilirubin >2×ULN without a confirmed alternative cause: permanently discontinue. Footnote b directs an alternative cause to the AST/ALT-only recommendations.',3,'Table 1 / footnote b p6')
    rule('HEPATITIS_COMBINED_CAUSE_REVIEW',all_(combo,c('hepatitis_alternative_cause_confirmed','not_exists')),'withhold','Concurrent AST/ALT >3×ULN and bilirubin >2×ULN can require permanent discontinuation. Alternative-cause status is unassessed: withhold and urgently establish cause before assigning the combination stop rule.',3,'Table 1 / footnote b p6')
    rule('HEPATITIS_COMBINED_ALTERNATIVE',all_(combo,c('hepatitis_alternative_cause_confirmed','==',True)),'consultant_review','A confirmed alternative cause invokes footnote b: use the AST/ALT recommendations without the concurrent-bilirubin rule. Independent severe laboratory or other stop criteria remain visible.',6,'Table 1 footnote b')
    for f in ['creatinine_ratio_baseline_or_uln','creatinine_baseline_ratio','creatinine_uln_ratio']:
        suffix='' if f=='creatinine_ratio_baseline_or_uln' else '_BASELINE' if f=='creatinine_baseline_ratio' else '_ULN'
        rule('ICI_RENAL_G2'+suffix,between(f,1.5,3),'withhold','Immune nephritis with creatinine >1.5 to 3×baseline or ULN (source grade 2): withhold. Confirm the denominator and clinical cause; an absolute creatinine value is not a ratio.',4)
        rule('ICI_RENAL_G3'+suffix,c(f,'>',3),'permanently_discontinue','Immune nephritis: creatinine >3×baseline, or >3–6×ULN (grade 3), or >6×ULN (grade 4) requires permanent discontinuation.',4)
    rule('RASH_G2_OVER_WEEK',any_(all_(c('rash_grade','==',2),c('rash_duration_days','>',7)),c('rash_grade_2_over_one_week','==',True)),'withhold','Grade 2 immune rash/dermatitis persisting more than one week: withhold. At exactly one week this particular duration criterion is not met.',4)
    rule('RASH_G3',c('rash_grade','==',3),'withhold','Grade 3 immune rash/dermatitis: withhold and manage using the appropriate CTCAE 4.03 skin term.',4)
    rule('RASH_G4',c('rash_grade','==',4),'permanently_discontinue','Grade 4 immune skin toxicity: permanently discontinue. Confirm a skin diagnosis for which grade 4 is defined; do not label uncomplicated maculopapular rash grade 4.',4)
    for f,legacy,id in [('hyperthyroidism_grade','symptomatic_hyperthyroidism_or_thyroiditis','ENDOCRINE_HYPERTHYROID_THYROIDITIS'),('adrenal_hypophysitis_grade','symptomatic_adrenal_insufficiency_or_hypophysitis','ENDOCRINE_ADRENAL_HYPOPHYSITIS')]:
        trigger=any_(c(f,'>=',2),c('endocrine_status','==',legacy))
