    rule('MYOSITIS_RESPIRATORY_STOP',c('myositis_respiratory_insufficiency','==',True),'permanently_discontinue','Myositis with respiratory insufficiency: permanently discontinue (Table 1 footnote d).',6,'Table 1 footnote d')
    rule('MYOSITIS_30_DAY_STOP',c('myositis_days_without_grade1_recovery','>=',30),'permanently_discontinue','Myositis not resolved to grade 1 or less within 30 days: permanently discontinue. Confirm onset, current grade and timing.',6,'Table 1 footnote d')
    rule('TRANSVERSE_MYELITIS_STOP',c('transverse_myelitis','==',True),'permanently_discontinue','Immune-mediated transverse myelitis of any grade: permanently discontinue.',5)
