    rule('SEVERE_IMMUNE_ENDOCRINE_EXCEPTION',all_(severe,c('endocrine_controlled_replacement','==',True)),'consultant_review','Controlled endocrinopathy is the source exception to the general severe/recurrent stop rule. Confirm this applies to the actual event; it never overrides a separate pneumonitis, myocarditis or other organ-specific stop rule.',6,'Restart paragraph')
