    rule('NONIMMUNE_G4_LAB_REVIEW',all_(c('other_nonimmune_toxicity_grade','==',4),any_(c('nonimmune_grade4_lab_only','==',True),c('nonimmune_grade4_lab_only','not_exists'))),'consultant_review','For grade 4 laboratory abnormalities, the discontinuation decision depends on clinical signs/symptoms and judgement. Establish whether this is laboratory-only; do not force permanent discontinuation from a grade alone.',6,'Table 1 footnote e')
    rule('RESTART_RESIDUAL_GRADE',all_(c('assessment_type','==','restart'),c('restart_residual_immune_grade','>',1)),'withhold','After an immune-toxicity hold, the source restart criterion requires recovery to grade ≤1. Any organ-specific permanent stop remains in force.',6,'Restart paragraph')
    rule('RESTART_STEROIDS',all_(c('assessment_type','==','restart'),c('systemic_steroids_mg_pred','>',10)),'withhold','After an immune-toxicity hold, the source restart criterion requires systemic steroids reduced to ≤10 mg prednisone/day equivalent. Do not abruptly stop steroids.',6,'Restart paragraph')
    rule('RESTART_OUTSIDE_WINDOW',all_(c('assessment_type','==','restart'),c('weeks_since_immune_hold','>',12)),'consultant_review','NCCP permits resumption within 12 weeks when recovery/steroid conditions are met. Outside that window requires consultant review; this text is not encoded as an invented automatic permanent-stop threshold.',6,'Restart paragraph')
    rule('RESTART_REVIEW',all_(c('assessment_type','==','restart'),c('restart_residual_immune_grade','<=',1),c('systemic_steroids_mg_pred','<=',10),c('weeks_since_immune_hold','<=',12)),'consultant_review','Entered recovery, steroid and timing criteria meet the general source resumption conditions; consultant approval and absence of any organ-specific permanent-stop event are still required. No automatic restart clearance.',6,'Restart paragraph')
    for f in ['renal_impairment_severity','hepatic_impairment_severity']:
        rule(f.upper()+'_SEVERE',c(f,'==','severe'),'consultant_review','Data in severe renal/hepatic impairment are too limited for conclusions. Obtain specialist assessment; no invented numeric dose reduction is supplied.',6,'Table 2')
        rule(f.upper()+'_MILD_MODERATE',c(f,'in',['mild','moderate']),'proceed_with_caution','NCCP recommends no adjustment for mild/moderate baseline organ impairment. This does not override immune nephritis/hepatitis or other toxicity criteria.',6,'Table 2')
    rule('FBC_ABNORMALITY_REVIEW',c('fbc_clinical_concern','==',True),'consultant_review','Review concerning blood counts clinically. The durvalumab source does not specify cytotoxic ANC/platelet dose-hold thresholds.',2,'Tests')
    p['rule_engine']['rules']=rules;p['required_inputs']=[]
    for x in d.values():x['required']=False
    p['metadata'].update({'nccp_version':version,'source_url':url,'source_document_pages':9,'source_pdf_sha256':SOURCES[code]['sha256'],'source_retrieved_date':DATE,'source_checked_date':DATE,'sactcheck_encoding_version':'0.84.22','assessment_model':'single_agent_ici','indication':'Adult PD-L1 ≥1% unresectable stage III NSCLC without progression after definitive concurrent platinum chemoradiation.','treatment_intent':'Consolidation after definitive concurrent CRT in a curative-intent stage III pathway','source_ctcae_version':'4.03'})
    p['metadata']['encoding_maturity']={'level':'source_reconciled_pending_independent_validation','label':'Source reconciled · independent clinical and pharmacy validation pending','source_reconciled':True,'consultant_reviewed':False,'oncology_pharmacy_reviewed':False,'clinical_use_authorised':False,'audit_release':'0.84.22','audit_date':DATE,'scope_note':'Fresh official source, page/table boundaries and executable rules reconciled; this is not independent clinical authorisation.'}
    p['metadata']['validation'].update({'rule_level_source_reconciliation_status':'source_reconciled_pending_independent_clinical_and_oncology_pharmacy_validation','consultant_reviewed':False,'oncology_pharmacy_reviewed':False,'clinical_use_authorised':False})
    p['indications']=[{'indication_id':code+'a','description':p['metadata']['indication']}]
    p.setdefault('treatment',{}).update({'cycle_length_days':days,'schedule_summary':f'Durvalumab {dose} {unit} IV Day 1 every {days} days, maximum 12 months ({cycles} cycles); start within 42 days after CRT.','drugs':['durvalumab']})
    p['treatment_phases']=[{'phase_id':'consolidation','label':'Durvalumab consolidation after completed concurrent CRT','cycle_length_days':days,'planned_cycles':cycles,'active_drugs':['durvalumab'],'duration_text':f'Until progression or unacceptable toxicity, maximum 12 months ({cycles} cycles). Begin cycle 1 within 42 days of completing concurrent CRT.','administration':[{'day':1,'order':1,'drug':'durvalumab','dose':{'value':dose,'unit':unit},'route':'IV infusion','notes':'250 mL sodium chloride 0.9% over 60 minutes; low-protein-binding 0.2–0.22 micrometre inline filter; separate line. Final concentration 1–15 mg/mL.'+(' At body weight ≤30 kg, fixed 1500 mg must not be used: separately prescribe 10 mg/kg q2w or 20 mg/kg q4w until >30 kg.' if code=='00655' else '')}]}]
    p['eligibility']={'summary':'Adults, ECOG 0–1, PD-L1 ≥1%, unresectable stage III NSCLC, no progression after ≥2 concurrent platinum cycles and ≥60 Gy radiation; adequate organ function.','source':{'url':url,'page':1}}
    p['exclusions']={'summary':'See source p2 and executable exclusion/caution rules; sequential CRT and mixed SCLC/NSCLC are outside scope. Prior PD-1/PD-L1 treatment refers to separate NCCP policy.','source':{'url':url,'page':2}}
    p['monitoring']={'baseline':['FBC, renal/liver profile, blood glucose and thyroid function','HBsAg, HBcoreAb and hepatitis C screening','Validated PD-L1; review CRT timing, radiation-related pulmonary effects and medicines'],'regular':['FBC, renal/liver profile, glucose and thyroid function regularly per team plan','Review immune, pulmonary, endocrine and infection symptoms before treatment and between visits','Disease monitoring according to consultant treatment plan'],'source':{'url':url,'page':'2–3, 7–8'}}
    p['dose_modifications']={'summary':'Dose escalation/reduction is not recommended for durvalumab toxicity. Apply withholding/discontinuation criteria and consultant review; general resumption within 12 weeks requires grade ≤1 and prednisone equivalent ≤10 mg/day. CTCAE4.03 is the NCCP table standard.','source':{'url':url,'page':'3–6'}}
    p['clinical_governance']['dose_modification_note']='Consultant discussion of every modification. No dose-reduction ladder. Omitted domains remain unassessed; source Table1 CTCAE4.03 and specific event identity take precedence over generic grades.'
    out=HERE/'proposed'/original.name;save(out,p)
    manifest['protocols'][code]={'protocol_id':p['protocol_id'],'source_path':str(original.relative_to(ROOT)),'proposed_path':str(out.relative_to(ROOT)),'rule_count':len(rules),'input_count':len(d),'source_url':url,'source_version':version,'source_pdf_sha256':SOURCES[code]['sha256']}
